/* setReply */
INSERT INTO TB_REPLXX (
            REPT_NUMB
          , UPER_NUMB
          , USER_NUMB
          , REPL_CNTN
          , DELT_YSNO
          , REGI_DATE
          , UPDT_DATE
) VALUES (  #{reptNumb}
          , #{uperNumb,jdbcType=NUMERIC}
          , #{userNumb}
          , #{replCntn}
          , #{deltYsno}
          , CURRENT_TIMESTAMP
          , NULL
)

mapper.update:

UPDATE /* uptReply */
       TB_REPLXX R
   SET REPL_CNTN = #{replCntn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE R.REPT_NUMB = #{reptNumb}
   AND R.REPL_NUMB = #{replNumb}
   AND R.USER_NUMB = #{userNumb}
   AND R.DELT_YSNO = #{commNo}
   AND SHA2(CONCAT_WS('|'
            , COALESCE(R.REPL_CNTN, '')
            , COALESCE(R.DELT_YSNO, '')
       ), 256) = #{editVersion}
   AND EXISTS (
           SELECT 1
             FROM TM_USERXM U
            WHERE U.USER_NUMB = #{userNumb}
              AND U.USER_STAT = #{userStatActive}
       )

mapper.select:

SELECT /* getReplyLikeTarget */
       R.REPT_NUMB
     , R.REPL_NUMB
     , R.USER_NUMB AS TARGET_USER_NUMB
  FROM TB_REPLXX R
  JOIN TM_USERXM U
    ON U.USER_NUMB = #{userNumb}
   AND U.USER_STAT = #{userStatActive}
 WHERE R.REPT_NUMB = #{reptNumb}
   AND R.REPL_NUMB = #{replNumb}
   AND R.DELT_YSNO = #{commNo}

mapper.insert:

/* setReplyLike */
INSERT IGNORE INTO TB_LIKEXX (
       USER_NUMB
     , TAGT_TYPE
     , TAGT_NUMB
     , REGI_DATE
) SELECT #{userNumb}
       , #{likeTargetReply}
       , #{replNumb}
       , CURRENT_TIMESTAMP
    FROM DUAL
   WHERE EXISTS (
           SELECT 1
             FROM TB_REPLXX R
             JOIN TM_USERXM U
               ON U.USER_NUMB = #{userNumb}
              AND U.USER_STAT = #{userStatActive}
            WHERE R.REPT_NUMB = #{reptNumb}
              AND R.REPL_NUMB = #{replNumb}
              AND R.DELT_YSNO = #{commNo}
       )

mapper.delete:

DELETE /* delReplyLike */ L
  FROM TB_LIKEXX L
 WHERE L.USER_NUMB = #{userNumb}
   AND L.TAGT_TYPE = #{likeTargetReply}
   AND L.TAGT_NUMB = #{replNumb}
   AND EXISTS (
           SELECT 1
             FROM TB_REPLXX R
             JOIN TM_USERXM U
               ON U.USER_NUMB = #{userNumb}
              AND U.USER_STAT = #{userStatActive}
            WHERE R.REPT_NUMB = #{reptNumb}
              AND R.REPL_NUMB = #{replNumb}
              AND R.DELT_YSNO = #{commNo}
       )

mapper.select:

SELECT /* getReplyLikeDtl */
       #{reptNumb} AS REPT_NUMB
     , #{replNumb} AS REPL_NUMB
     , COUNT(L.USER_NUMB) AS LIKE_CNT
     , CASE WHEN MAX(CASE WHEN L.USER_NUMB = #{userNumb} THEN 1 ELSE 0 END) = 1
                 THEN #{commYes}
            ELSE #{commNo}
        END AS LIKE_YSNO
  FROM TB_LIKEXX L
  JOIN TM_USERXM U
    ON U.USER_NUMB = L.USER_NUMB
   AND U.USER_STAT = #{userStatActive}
 WHERE L.TAGT_TYPE = #{likeTargetReply}
   AND L.TAGT_NUMB = #{replNumb}

mapper.update:

UPDATE /* delReply */
       TB_REPLXX R
   SET DELT_YSNO = #{commYes}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE R.REPT_NUMB = #{reptNumb}
   AND R.REPL_NUMB = #{replNumb}
   AND R.USER_NUMB = #{userNumb}
   AND R.DELT_YSNO = #{commNo}
   AND EXISTS (
           SELECT 1
             FROM TM_USERXM U
            WHERE U.USER_NUMB = #{userNumb}
              AND U.USER_STAT = #{userStatActive}
       )
